namespace sv_ccc0d6b9914f4c539f16bb9166369dba.Services;

public class DoctorInfo
{
    public string Name { get; set; } = string.Empty;
    public bool AcceptsSelfPay { get; set; }
}

public class ValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public Dictionary<string, string> Errors { get; set; } = new();
}

public interface IAppointmentService
{
    Task<List<DoctorInfo>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date);
    Task<ValidationResult> ValidatePatientAsync(string email, string insuranceProvider, string doctorName, string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    private static readonly List<DoctorInfo> Doctors =
    [
        new() { Name = "Dr. Smith", AcceptsSelfPay = false },
        new() { Name = "Dr. Johnson", AcceptsSelfPay = true },
        new() { Name = "Dr. Williams", AcceptsSelfPay = true },
        new() { Name = "Dr. Brown", AcceptsSelfPay = false },
    ];

    private static readonly List<string> AllSlots =
    [
        "9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM",
        "11:00 AM", "11:30 AM", "1:00 PM", "1:30 PM",
        "2:00 PM", "2:30 PM", "3:00 PM", "3:30 PM",
    ];

    public Task<List<DoctorInfo>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<DoctorInfo>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date)
    {
        // Stub: return all slots for any valid doctor/date combination
        return Task.FromResult(new List<string>(AllSlots));
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email, string insuranceProvider, string doctorName, string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(AppointmentModel.Email)] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.OrdinalIgnoreCase)
            && string.Equals(doctorName, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(AppointmentModel.Doctor)] = "Selected doctor does not accept self-pay patients";
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            result.Errors[nameof(AppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_ccc0d6b9914f4c539f16bb9166369dba.Services;

public class AppointmentModel
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select an insurance provider.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a doctor.")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a date.")]
    [FutureDate(ErrorMessage = "Date must be in the future.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

public class FutureDateAttribute : ValidationAttribute
{
    public override bool IsValid(object? value)
    {
        if (value is DateOnly date)
        {
            return date > DateOnly.FromDateTime(DateTime.Today);
        }
        return false;
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_ccc0d6b9914f4c539f16bb9166369dba.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ── STEP 1 ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.TryGetValue(nameof(Model.Email), out var emailErr))
            {
                <div class="validation-message">@emailErr</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="GoToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ── STEP 2 ── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc.Name">@doc.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.TryGetValue(nameof(Model.Doctor), out var docErr))
                {
                    <div class="validation-message">@docErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.TryGetValue(nameof(Model.TimeSlot), out var slotErr))
                {
                    <div class="validation-message">@slotErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">Back</button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
                    @(isChecking ? "Checking…" : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || hasServerErrors)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();

    private List<DoctorInfo> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();

    private bool showStep2;
    private bool isChecking;
    private bool availabilityChecked;
    private bool submitted;

    private bool hasServerErrors => serverErrors.Count > 0;

    // Tracks which step-1 fields to validate before advancing
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // Cache EditContext after the form is built
        if (editContext is null)
        {
            editContext = new EditContext(Model);
            editContext.EnableDataAnnotationsValidation();
        }
    }

    private void GoToStep2()
    {
        // Validate only step-1 fields
        editContext ??= new EditContext(Model);
        editContext.EnableDataAnnotationsValidation();
        editContext.Validate();

        var messages = editContext.GetValidationMessages();
        // Check if any validation message belongs to a step-1 field
        bool step1Valid = !Step1Fields
            .SelectMany(f => editContext.GetValidationMessages(
                new FieldIdentifier(Model, f)))
            .Any();

        if (step1Valid)
        {
            showStep2 = true;
            availabilityChecked = false;
            serverErrors.Clear();
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService
                .GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate.Value);
            // Reset selection when slots reload
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;
        isChecking = true;

        try
        {
            var result = await AppointmentService.ValidatePatientAsync(
                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

            if (result.IsValid)
            {
                availabilityChecked = true;
            }
            else
            {
                serverErrors = new Dictionary<string, string>(result.Errors);
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (!availabilityChecked || hasServerErrors)
            return;

        submitted = true;
    }
}

